public interface IPlacementService
{
    PlacementResult Place(Job job, Resource resource);
    PlacementResult Reschedule(Job job, Resource resource);
    bool IsPlaced(string jobId);
}

public sealed class BookingService
{
    private readonly List<Slot> _booked = new();
    private readonly IBookingPolicy _policy;

    public BookingService(IBookingPolicy policy) => _policy = policy;

    public bool Book(Slot candidate)
    {
        if (!_policy.IsValid(candidate) ||
            _booked.Any(x => x.Start < candidate.End && candidate.Start < x.End))
            return false;

        _booked.Add(candidate);
        return true;
    }
}

public sealed class ScheduleCoordinator
{
    private readonly IPlacementService _placements;
    private readonly INotificationService _notifications;

    public ScheduleCoordinator(
        IPlacementService placements,
        INotificationService notifications)
    {
        _placements = placements;
        _notifications = notifications;
    }

    public PlacementResult PlaceAndNotify(Job job, Resource resource)
    {
        var result = _placements.Place(job, resource);
        if (result.Succeeded)
